<?php require_once __DIR__.'/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id){flash('error','ID produk tidak valid.');header('Location: index.php');exit;}$stmt=$pdo->prepare('DELETE FROM products WHERE id = ?');$stmt->execute([$id]);flash('success',$stmt->rowCount()?'Produk berhasil dihapus.':'Produk tidak ditemukan.');header('Location: index.php');exit;
